def kline_rows(code,target,end_target=None):
    end_target=end_target or target
    cache_key=(code,target.isoformat(),end_target.isoformat())
    if cache_key in KLINE_CACHE:return KLINE_CACHE[cache_key]
    # 沪市可转债以 11 开头；其余现有记录按股票/基金常用代码前缀判断。
    market='sh' if code.startswith(('5','6','9','11')) else 'sz';secid=('1.' if market=='sh' else '0.')+code
    start=(target.replace(day=1)-timedelta(days=10)).strftime('%Y%m%d')
    end=(end_target+timedelta(days=3)).strftime('%Y%m%d')
    rows=[]
    try:
        params={'secid':secid,'klt':'101','fqt':'0','lmt':'1000','beg':start,'end':end,'fields1':'f1,f2,f3,f4,f5,f6','fields2':'f51,f52,f53,f54,f55,f56','ut':'fa5fd1943c7b386f172d6893dbfba10b'}
        response=requests.get('https://push2his.eastmoney.com/api/qt/stock/kline/get',params=params,headers=HEADERS,timeout=20)
        response.raise_for_status();lines=(response.json().get('data') or {}).get('klines') or []
        for line in lines:
            cells=line.split(',')
            if len(cells)>=5:rows.append({'date':date.fromisoformat(cells[0]),'close':number(cells[2]),'high':number(cells[3]),'low':number(cells[4])})
    except (requests.RequestException,ValueError,TypeError):pass
    if rows:
        result=[x for x in rows if x['high']>0 and x['low']>0];KLINE_CACHE[cache_key]=result;return result
    try:
        symbol=market+code
        param=f'{symbol},day,{start[:4]}-{start[4:6]}-{start[6:]},{end[:4]}-{end[4:6]}-{end[6:]},80,'
        response=requests.get('https://web.ifzq.gtimg.cn/appstock/app/fqkline/get',params={'param':param},headers=HEADERS,timeout=20)
        response.raise_for_status();data=(response.json().get('data') or {}).get(symbol) or {};raw=data.get('day') or []
        for cells in raw:
            if len(cells)>=5:rows.append({'date':date.fromisoformat(cells[0]),'close':number(cells[2]),'high':number(cells[3]),'low':number(cells[4])})
    except (requests.RequestException,ValueError,TypeError):pass
    result=[x for x in rows if x['high']>0 and x['low']>0];KLINE_CACHE[cache_key]=result;return result

functions.evaluate_recommendations:
def evaluate_recommendations(payload):
    today=datetime.now(BJ).date();changed=False
    for record in payload.get('records') or []:
        if record.get('action')!='分批买入':
            evaluation=record.get('evaluation') or {}
            if evaluation.get('status')!='not_scored':
                record['evaluation']={'status':'not_scored','reason':'非明确买入指令，不计入买入命中率'};changed=True
            continue
        try:start=date.fromisoformat(str(record.get('recommendedAt') or record.get('date'))[:10])
        except ValueError:continue
        entry=number((record.get('snapshot') or {}).get('price'))
        if not entry:continue
        all_rows=kline_rows(str(record.get('code') or ''),start,today)
        rows=[x for x in all_rows if start<x['date']<=today][:30]
        target=entry*1.05;hit=next((x for x in rows if x['high']>=target),None);weekly_hit=None
        for index,bar in enumerate(rows):
            iso=bar['date'].isocalendar();week=[x for x in all_rows if x['date']<=bar['date'] and x['date'].isocalendar()[:2]==iso[:2]]
            item=position_item(bar['close'],week)
            if item and item['zone']=='上部' and bar['close']>entry:weekly_hit=bar;break
        max_high=max((x['high'] for x in rows),default=entry);latest_close=rows[-1]['close'] if rows else entry
        evaluation={'status':'success' if hit else ('failed' if len(rows)>=30 else ('pending' if rows else 'no_data')),'criterion':'30个交易日内最高价达到指令价+5%','entryPrice':round(entry,3),'targetPrice':round(target,3),'observedTradingDays':len(rows),'maxGainPct':round((max_high/entry-1)*100,3),'latestReturnPct':round((latest_close/entry-1)*100,3)}
        if hit:evaluation.update({'firstHitAt':hit['date'].isoformat(),'tradingDaysToHit':rows.index(hit)+1,'calendarDaysToHit':(hit['date']-start).days})
        if weekly_hit:evaluation.update({'weeklyUpperFirstAt':weekly_hit['date'].isoformat(),'tradingDaysToWeeklyUpper':rows.index(weekly_hit)+1,'calendarDaysToWeeklyUpper':(weekly_hit['date']-start).days})
        previous=record.get('evaluation') or {};previous_core={k:v for k,v in previous.items() if k!='evaluatedAt'}
        if previous_core!=evaluation:
            evaluation['evaluatedAt']=datetime.now(BJ).isoformat(timespec='seconds');record['evaluation']=evaluation;changed=True
    return changed,recommendation_stats(payload.get('records') or [])

functions.WorkerError:
class WorkerError(RuntimeError):
    """A safe, non-sensitive worker failure category."""

    def __init__(self, category: str):
        super().__init__(category)
        self.category = category

functions.canonical_username:
def canonical_username(value: str) -> str:
    normalized = unicodedata.normalize("NFKC", str(value or "")).strip().lower()
    if not USERNAME_RE.fullmatch(normalized):
        raise WorkerError("username_invalid")
    return normalized

functions.valid_https_url:
def valid_https_url(value: str) -> str:
    parsed = urlparse(str(value or "").rstrip("/"))
    if parsed.scheme != "https" or parsed.username or parsed.password or parsed.query or parsed.fragment:
        raise WorkerError("supabase_url_invalid")
    if parsed.path not in ("", "/") or not parsed.netloc:
        raise WorkerError("supabase_url_invalid")
    return str(value).rstrip("/")

functions.load_config:
def load_config(worker_dir: Path) -> dict[str, str]:
    path = config_path(worker_dir)
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as error:
        raise WorkerError("worker_not_setup") from error
    except (OSError, ValueError) as error:
        raise WorkerError("worker_config_invalid") from error
    if not isinstance(value, dict):
        raise WorkerError("worker_config_invalid")
    required = {"schemaVersion", "supabaseUrl", "supabaseAnonKey", "username", "keychainService", "keychainAccount"}
    if not required.issubset(value):
        raise WorkerError("worker_config_invalid")
    if value.get("schemaVersion") != 1:
        raise WorkerError("worker_config_version_unsupported")
    # A config file must never become a password/token cache.
    forbidden = {"password", "access_token", "refresh_token", "service_role", "api_key", "openai_api_key"}
    if forbidden.intersection(str(key).lower() for key in value):
        raise WorkerError("worker_config_contains_credential")
    username = canonical_username(str(value.get("username", "")))
    service = str(value.get("keychainService", ""))
    account = str(value.get("keychainAccount", ""))
    if service != KEYCHAIN_SERVICE or account != username:
        raise WorkerError("worker_keychain_binding_invalid")
    supabase_url = valid_https_url(str(value["supabaseUrl"]))
    if supabase_url != EXPECTED_SUPABASE_URL:
        raise WorkerError("worker_config_invalid")
    anon_key = str(value["supabaseAnonKey"]).strip()
    if not anon_key or len(anon_key) > 512:
        raise WorkerError("worker_config_invalid")
    return {
        "schemaVersion": "1",
        "supabaseUrl": supabase_url,
        "supabaseAnonKey": anon_key,
        "username": username,
        "keychainService": service,
        "keychainAccount": account,
    }

functions.keychain_read:
def keychain_read(service: str, account: str) -> str:
    if "DASHBOARD_SECRET_DIR" in os.environ:
        from dashboard_secret_store import SecretStoreError, read
        try:
            return read(service, account)
        except SecretStoreError as error:
            raise WorkerError(str(error)) from None
    completed = subprocess.run(
        ["security", "find-generic-password", "-a", account, "-s", service, "-w"],
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    value = completed.stdout.strip()
    if completed.returncode != 0 or not value or "\n" in value or "\r" in value:
        raise WorkerError("worker_refresh_token_missing")
    return value

functions.keychain_write:
def keychain_write(service: str, account: str, value: str) -> None:
    if "DASHBOARD_SECRET_DIR" in os.environ:
        from dashboard_secret_store import SecretStoreError, write
        try:
            write(service, account, value)
        except SecretStoreError as error:
            raise WorkerError(str(error)) from None
        return
    if not value or "\n" in value or "\r" in value or "\x00" in value:
        raise WorkerError("worker_refresh_token_invalid")
    # ``security -w`` reads from its controlling terminal rather than ordinary
    # stdin. It also consumes each value only after printing its corresponding
    # prompt, so preloading a pipe/PTY can lose both values. ``pty.fork()``
    # gives the child its own no-echo controlling terminal; the parent waits
    # for each fixed prompt before supplying the opaque refresh token. Nothing
    # is placed in argv, shell history, a file, or terminal output.
    child_pid: int | None = None
    master_fd: int | None = None
    try:
        child_pid, master_fd = pty.fork()
        if child_pid == 0:
            try:
                attributes = termios.tcgetattr(0)
                attributes[3] &= ~termios.ECHO
                termios.tcsetattr(0, termios.TCSANOW, attributes)
                os.execvp(
                    "security",
                    ["security", "add-generic-password", "-U", "-a", account, "-s", service, "-w"],
                )
            except BaseException:
                os._exit(127)

        prompt_buffer = bytearray()
        first_sent = False
        second_sent = False
        deadline = time.monotonic() + 30
        exit_status: int | None = None
        while time.monotonic() < deadline:
            ended_pid, status = os.waitpid(child_pid, os.WNOHANG)
            if ended_pid == child_pid:
                exit_status = status
                break
            readable, _, _ = select.select([master_fd], [], [], 0.25)
            if not readable:
                continue
            try:
                chunk = os.read(master_fd, 4096)
            except OSError:
                chunk = b""
            if not chunk:
                continue
            prompt_buffer.extend(chunk.lower())
            # Keep the detector bounded. With ECHO disabled, the token itself
            # is never returned by the PTY; this buffer is never logged.
            if len(prompt_buffer) > 4096:
                del prompt_buffer[:-1024]
            if not first_sent and b"password data for new item:" in prompt_buffer:
                os.write(master_fd, (value + "\n").encode("utf-8"))
                first_sent = True
            if first_sent and not second_sent and b"retype password for new item:" in prompt_buffer:
                os.write(master_fd, (value + "\n").encode("utf-8"))
                second_sent = True
        if exit_status is None:
            os.kill(child_pid, 9)
            _, exit_status = os.waitpid(child_pid, 0)
        if not (first_sent and second_sent and os.WIFEXITED(exit_status) and os.WEXITSTATUS(exit_status) == 0):
            raise WorkerError("worker_keychain_write_failed")
    except (OSError, ValueError) as error:
        raise WorkerError("worker_keychain_write_failed") from error
    finally:
        if master_fd is not None:
            os.close(master_fd)
    try:
        stored = keychain_read(service, account)
    except WorkerError as error:
        raise WorkerError("worker_keychain_write_failed") from error
    if stored != value:
        raise WorkerError("worker_keychain_write_failed")

